const body = $json.body ?? $json;
const itinerary = Array.isArray(body.itinerary) ? body.itinerary : [];
if (!itinerary.length) {
  throw new Error('Payload invalido. Esperado: { itinerary: [{ city, lat, lon, date }] }');
}
return itinerary.map((item, idx) => ({
  json: {
    index: idx,
    city: item.city,
    lat: Number(item.lat),
    lon: Number(item.lon),
    date: item.date
  }
}));

const input = $items('Split In Batches', 0, 0)[0].json;
const d = $json.daily || {};
const dates = d.time || [];
const idx = Math.max(0, dates.indexOf(input.date));
const tempMax = (d.temperature_2m_max || [])[idx] ?? null;
const tempMin = (d.temperature_2m_min || [])[idx] ?? null;
const rainProb = (d.precipitation_probability_max || [])[idx] ?? null;
const uvMax = (d.uv_index_max || [])[idx] ?? null;

const checklist = [];
if (tempMin !== null && tempMin < 15) checklist.push('Levar casaco');
if (tempMax !== null && tempMax > 28) checklist.push('Levar roupas leves');
if (rainProb !== null && rainProb >= 40) checklist.push('Levar guarda-chuva/capa de chuva');
if (uvMax !== null && uvMax >= 6) checklist.push('Levar protetor solar');
if (!checklist.length) checklist.push('Levar itens basicos para clima ameno');

return [{
  json: {
    index: input.index,
    city: input.city,
    date: input.date,
    forecast: {
      temp_max_c: tempMax,
      temp_min_c: tempMin,
      rain_probability_max: rainProb,
      uv_index_max: uvMax
    },
    checklist,
    metadata: {
      confidence: 'medium',
      source: 'open-meteo.com',
      generated_at: new Date().toISOString()
    }
  }
}];

const rows = items.map(i => i.json).sort((a, b) => a.index - b.index);
return [{
  json: {
    itinerary_weather: rows.map(r => ({
      city: r.city,
      date: r.date,
      forecast: r.forecast
    })),
    checklists: rows.map(r => ({
      city: r.city,
      date: r.date,
      items: r.checklist,
      metadata: r.metadata
    }))
  }
}];
